// Turns a flagged segment from Workflow 2 or 3 into a fact sheet. Only these facts reach the AI.
// Work orders: red / red-uncertain always; amber only when Workflow 3 escalates it (heavy weather forecast, priority high).
const RED = ['red', 'red-uncertain'];
const LF = String.fromCharCode(10);
const parse = (v, dflt) => {
  if (v == null || v === '') return dflt;
  if (typeof v !== 'string') return v;
  try { return JSON.parse(v); } catch (e) { return dflt; }
};
const out = [];
for (const it of $input.all()) {
  const j = it.json || {};
  const seg = String(j.segment_id || '').trim();
  const tier = String(j.tier || '').trim();
  const escalatedAmber = tier === 'amber' && j.priority === 'high';
  if (!seg || !(RED.includes(tier) || escalatedAmber)) continue;
  const drivers = parse(j.drivers_json, []);
  const near = parse(j.near_term_json, null);
  const facts = [
    'Segment: ' + seg,
    'Horizon: ' + (j.horizon || 'y10'),
    'Risk score (0-100): ' + (j.score != null && j.score !== '' ? j.score : 'not available'),
    'Risk tier: ' + tier,
    'Model agreement on extreme-rain direction: ' + (j.agreement || 'not available'),
  ];
  if (j.slope_pct != null && j.slope_pct !== '') facts.push('Slope: ' + j.slope_pct + '% grade');
  (Array.isArray(drivers) ? drivers : []).slice(0, 3).forEach((d, k) => {
    if (!d || !d.label) return;
    let line = 'Driver ' + (k + 1) + ': ' + d.label;
    if (d.key === 'slope') line += ', ' + d.change + '% grade';
    else if (d.change != null) line += ', change ' + d.change + '%';
    if (d.base != null) line += ', baseline ' + d.base + ' per year';
    if (d.proj != null) line += ', projected ' + d.proj + ' per year';
    facts.push(line);
  });
  if (near && near.events && near.events.length) {
    near.events.slice(0, 3).forEach((e) => facts.push('Near-term forecast (' + e.date + '): ' + e.text));
  }
  const top = (Array.isArray(drivers) && drivers[0]) || null;
  out.push({ json: {
    work_order_id: 'WO-' + seg + '-' + Date.now().toString(36).toUpperCase(),
    segment_id: seg,
    tier,
    horizon: j.horizon || 'y10',
    score: j.score != null && j.score !== '' ? Number(j.score) : null,
    agreement: j.agreement || null,
    slope_pct: j.slope_pct != null && j.slope_pct !== '' ? Number(j.slope_pct) : null,
    priority: j.priority === 'high' ? 'high' : 'normal',
    trigger_source: j.trigger_source || 'workflow',
    top_driver_key: top ? top.key : null,
    top_driver_label: top ? top.label : null,
    facts,
    facts_text: facts.join(LF),
  } });
}
return out;

// One item out: the order that blocks a new draft for this segment, or {} if none.
// Blocks when an order is pending approval and still inside its 14-day approval window, or was approved in the last 7 days.
// An order waiting on landowner notice (awaiting_notice / notice_given) never goes stale. Expired orders never block.
const DAY = 24 * 3600 * 1000;
const NOTICE = ['awaiting_notice', 'notice_given'];
const rows = $input.all().map((i) => i.json).filter((r) => r && r.work_order_id);
const pending = rows.find((r) => r.status === 'pending_approval' && (NOTICE.includes(r.obligation_status) || !r.drafted_at || Date.now() - new Date(r.drafted_at).getTime() < 14 * DAY));
const recent = rows
  .filter((r) => r.status === 'approved' && r.decided_at && Date.now() - new Date(r.decided_at).getTime() < 7 * DAY)
  .sort((a, b) => String(b.decided_at).localeCompare(String(a.decided_at)))[0];
const b = pending || recent;
return [{ json: b ? { ...b, block_reason: pending ? 'pending_approval' : 'approved_within_7_days' } : {}, pairedItem: { item: 0 } }];

// Accept the AI text only if it is exactly two sentences and every number in it appears in the facts.
// Otherwise fall back to a fixed template built from the same facts.
const f = $('Build facts').item.json;
const raw = String(($json && $json.text) || '').replace(/\s+/g, ' ').trim();
const sentences = raw ? raw.split(/(?<=[.!?])\s+(?=[A-Z0-9])/).filter((s) => s.trim()) : [];
const nums = raw.match(/\d+(?:\.\d+)?/g) || [];
const unknownNums = nums.filter((n) => !f.facts_text.includes(n));
const INSPECT = {
  rain: 'drainage paths, culverts and surface erosion along the right-of-way',
  freezeThaw: 'frost heave, depth of cover and coating damage at exposed sections',
  saturation: 'saturated ground, seepage and early signs of soil creep',
  vegetation: 'vegetation loss and bare-soil erosion on the right-of-way',
  slope: 'tension cracks, scarps and ground movement on the steepest part of the segment',
};
let summary = raw, source = 'ai';
if (sentences.length !== 2 || unknownNums.length > 0) {
  source = 'template';
  const drv = f.top_driver_label ? f.top_driver_label + ' is the primary risk driver' : 'The combined risk factors drive the score';
  summary = drv + ' for ' + f.segment_id + ' (' + f.horizon + ' score ' + (f.score != null ? f.score : 'n/a') + ', tier ' + f.tier + ', model agreement ' + (f.agreement || 'n/a') + ').' +
    ' Field crews should first inspect ' + (INSPECT[f.top_driver_key] || 'the segment for ground movement and drainage problems') + '.';
}
return { json: {
  work_order_id: f.work_order_id,
  segment_id: f.segment_id,
  status: 'pending_approval',
  priority: f.priority,
  trigger_source: f.trigger_source,
  tier: f.tier,
  horizon: f.horizon,
  score: f.score,
  summary,
  summary_source: source,
  rejected_ai_text: source === 'template' ? raw : null,
  facts_json: JSON.stringify(f.facts),
  drafted_at: new Date().toISOString(),
} };

// Reads the v2 W8 obligation check for this work order.
// Notice owed (any applicable obligation with notice hours): awaiting_notice, earliest_start = now + the longest notice_hours.
// Otherwise W8's own status. Any failed check (no answer, not 200, ok:false) is unverified.
const base = $('Check summary').item.json;
const r = $json || {};
const body = r.body && typeof r.body === 'object' ? r.body : null;
const now = new Date();
let status, earliest = '', detail;
if (r.statusCode === 200 && body && body.ok === true) {
  const steps = Array.isArray(body.steps) ? body.steps : [];
  const notice = steps.filter((s) => Number(s.noticeHours) > 0);
  const hours = notice.reduce((m, s) => Math.max(m, Number(s.noticeHours) || 0), 0);
  status = notice.length ? 'awaiting_notice' : String(body.status || 'unverified');
  earliest = new Date(now.getTime() + hours * 3600000).toISOString();
  detail = { check: body.status || null, notice_hours: hours, notice_steps: notice.map((s) => s.id), steps, unverified: body.unverified || [], problems: body.problems || [], summary: body.summary || null };
} else {
  status = 'unverified';
  detail = { error: (body && body.error) || (r.error && (r.error.message || String(r.error))) || ('obligation check answered ' + (r.statusCode || 'nothing')) };
}
return { json: { ...base, obligation_status: status, earliest_start: earliest, needs_notice: status === 'awaiting_notice', obligation_json: JSON.stringify({ ...detail, checked_at: now.toISOString() }) } };

// Every dashboard click lands here (Header Auth: "TerraCorridor v2 webhook key"). Unknown actions are refused.
// Every action needs the name of the person making it (by). There is no default name.
const req = $input.first().json || {};
const b = req.body || {};
const ALLOWED = ['approve_work_order', 'reject_work_order', 'override_tier', 'confirm_notice', 'redraft_work_order'];
const TIERS = ['green', 'amber', 'red', 'red-uncertain', 'unverified'];
const action = String(b.action || '').trim();
const segment = String(b.segment || b.segment_id || '').trim();
const by = String(b.by || b.user || '').trim();
const details = b.details && typeof b.details === 'object' ? b.details : {};
const reason = String(details.reason || '').trim();
const toTier = String(details.to || '').trim();
// The dashboard sends horizon as 5 or 10; the API also accepts 'y5' / 'y10'.
const hRaw = String(details.horizon != null && details.horizon !== '' ? details.horizon : '10').trim().toLowerCase();
const horizon = hRaw === '5' || hRaw === 'y5' ? 'y5' : hRaw === '10' || hRaw === 'y10' ? 'y10' : '';
const errors = [];
if (!ALLOWED.includes(action)) errors.push('unknown action "' + action + '"; allowed: ' + ALLOWED.join(', '));
if (!segment) errors.push('missing segment');
if (!by) errors.push('missing by: the name of the person making this request');
const workOrderId = String(b.work_order_id || details.work_order_id || '').trim();
const noteText = String(details.note || '').trim();
let decisionReason = reason || noteText;
if (action === 'reject_work_order' && !decisionReason) errors.push('reject_work_order needs details.reason');
// Approve: optional planned start (ISO). It may not be earlier than the order's earliest_start.
let start = '';
if (action === 'approve_work_order' && details.start != null && details.start !== '') {
  const t = new Date(String(details.start));
  if (isNaN(t.getTime())) errors.push('details.start must be an ISO date-time'); else start = t.toISOString();
}
// Landowner notice: when and how notice was given. Sent to the approval gate as the reason.
let noticeAt = '';
if (action === 'confirm_notice') {
  const how = String(details.how || '').trim();
  const when = String(details.notice_given_at || '').trim();
  const t = new Date(when);
  if (!workOrderId) errors.push('confirm_notice needs work_order_id');
  if (!how) errors.push('confirm_notice needs details.how (how notice was given, for example "phoned landowner")');
  if (!when || isNaN(t.getTime())) errors.push('confirm_notice needs details.notice_given_at (when notice was given, ISO date-time)');
  else if (t.getTime() > Date.now() + 5 * 60000) errors.push('details.notice_given_at is in the future');
  else noticeAt = t.toISOString();
  decisionReason = how + ', ' + when;
}
if (action === 'redraft_work_order' && !workOrderId) errors.push('redraft_work_order needs work_order_id');
if (action === 'override_tier') {
  if (!reason) errors.push('override_tier needs a non-empty details.reason');
  if (!TIERS.includes(toTier)) errors.push('override_tier needs details.to, one of: ' + TIERS.join(', '));
  if (!horizon) errors.push('details.horizon must be 5, 10, y5 or y10');
}
return [{ json: {
  ok: errors.length === 0,
  error: errors.length ? errors.join('; ') : null,
  action,
  segment,
  by,
  decision: action === 'approve_work_order' ? 'approve' : action === 'reject_work_order' ? 'reject' : '',
  work_order_id: workOrderId,
  reason: decisionReason,
  start,
  notice_given_at: noticeAt,
  to_tier: toTier,
  horizon,
  note: String(details.note || reason || '').trim(),
  details_json: JSON.stringify({ details, score: b.score != null ? b.score : null }),
  score: b.score != null && b.score !== '' && Number.isFinite(Number(b.score)) ? Number(b.score) : null,
  // Shown to the manager when they pressed Approve (dashboard). Free text is trimmed and length-capped.
  req_tier: TIERS.includes(String(details.tier || '')) ? String(details.tier) : '',
  req_horizon: String(details.stop || '') === 'y5' ? 'y5' : 'y10',
  req_priority: /^P[123]$/.test(String(details.priority || '')) ? String(details.priority) : '',
  req_due: /^\d{4}-\d{2}-\d{2}$/.test(String(details.dueBy || '')) ? String(details.dueBy) : '',
  req_hazard: String(details.hazard || '').slice(0, 40),
  req_why: String(details.why || '').slice(0, 300),
  req_checks: Array.isArray(details.checks) ? details.checks.slice(0, 8).map((x) => String(x).slice(0, 240)) : [],
  req_map: /^https:\/\/www\.(openstreetmap\.org\/|google\.com\/maps[\/?])/.test(String(details.mapUrl || '')) ? String(details.mapUrl).slice(0, 200) : '',
  received_at: new Date().toISOString(),
} }];

// Decides whether this approve/reject can go to the approval gate (v2 W9).
// Refused here: an order past its 14-day approval window (410), approval while landowner notice is owed (409),
// and approval to start before earliest_start (409). Rejecting a pending order is always allowed.
const v = $('Validate action').first().json;
const DAY = 24 * 3600 * 1000;
const NOTICE = ['awaiting_notice', 'notice_given'];
const rows = $input.all().map((i) => i.json).filter((r) => r && r.work_order_id);
const order = v.work_order_id ? rows.find((r) => r.work_order_id === v.work_order_id) : rows.sort((a, b) => String(b.drafted_at || '').localeCompare(String(a.drafted_at || '')))[0];
const refuse = (code, error) => [{ json: { route: 'refuse', status_code: code, response: { ok: false, action: v.action, segment: v.segment, work_order_id: order ? order.work_order_id : (v.work_order_id || null), error } } }];
if (!order) return [{ json: { route: v.decision === 'approve' && !v.work_order_id ? 'manager' : 'no_order' } }];
// Orders drafted by the hackathon WF4 (they carry its Wait-node resume_url) stay with it until switch day.
if (order.resume_url) return refuse(409, 'This order was drafted by the hackathon WF4 and stays with it until switch day. v2 does not decide it.');
const stale = !NOTICE.includes(order.obligation_status) && order.drafted_at && Date.now() - new Date(order.drafted_at).getTime() >= 14 * DAY;
if (stale) return refuse(410, 'This order waited more than 14 days for approval and has expired. Redraft it to run a fresh obligation check.');
let chosen = null, start = '';
if (v.decision === 'approve') {
  if (!order.obligation_status) return refuse(409, 'This order has no land-obligation check, so it cannot be approved. Let it expire and redraft it: a redraft runs the check.');
  if (order.obligation_status === 'awaiting_notice') return refuse(409, 'Landowner notice is owed on this kilometre and has not been recorded. Record it with confirm_notice first.');
  start = v.start || new Date().toISOString();
  if (order.earliest_start && new Date(start).getTime() < new Date(order.earliest_start).getTime()) return refuse(409, 'The work cannot start before ' + order.earliest_start + '. Send details.start on or after that time.');
  chosen = 'start ' + start;
}
return [{ json: { route: 'decide', work_order_id: order.work_order_id, segment_id: order.segment_id, decision: v.decision, chosen, approved_start: start, inputs_hash: order.inputs_hash || '', facts_json: order.facts_json || '', obligation_json: order.obligation_json || '', obligation_status: order.obligation_status || '' } }];

// Manager-requested inspection: the integrity manager pressed Approve on a segment that has no automatic draft.
// One item out. If this segment already has an order approved in the last 7 days, or one pending, reuse it (no duplicate row).
// The new order is NOT approved here: it gets an obligation check, then goes to v2 W9 /decide (or waits for landowner notice).
// Nothing is emailed and no crew is dispatched by this workflow.
const v = $('Validate action').first().json;
const DAY = 24 * 3600 * 1000;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.work_order_id);
const NOTICE = ['awaiting_notice', 'notice_given'];
const dup = rows.filter((r) => (r.status === 'pending_approval' && (NOTICE.includes(r.obligation_status) || !r.drafted_at || Date.now() - new Date(r.drafted_at).getTime() < 14 * DAY)) || (r.status === 'approved' && r.decided_at && Date.now() - new Date(r.decided_at).getTime() < 7 * DAY))
  .sort((a, b) => String(b.drafted_at || '').localeCompare(String(a.drafted_at || '')))[0];
const now = new Date().toISOString();
if (dup) return [{ json: { duplicate: true, work_order_id: dup.work_order_id, segment_id: v.segment, status: dup.status, block_reason: dup.status === 'approved' ? 'approved_within_7_days' : 'pending_approval' } }];
const facts = ['Segment: ' + v.segment, 'Requested by: ' + v.by + ' (integrity manager, from the dashboard)', 'Horizon: ' + v.req_horizon,
  'Risk score (0-100): ' + (v.score != null ? v.score : 'not available'), 'Risk tier: ' + (v.req_tier || 'not available')];
if (v.req_hazard) facts.push('Worst hazard: ' + v.req_hazard);
if (v.req_why) facts.push('Main driver: ' + v.req_why);
if (v.req_due) facts.push('Due by: ' + v.req_due + (v.req_priority ? ' (' + v.req_priority + ')' : ''));
v.req_checks.forEach((c, i) => facts.push('Check ' + (i + 1) + ': ' + c));
if (v.req_map) facts.push('Location: ' + v.req_map);
facts.push('Next step: queued email handoff when SMTP delivery is configured, or CSV export for the inspection coordinator. No crew dispatch.');
return [{ json: {
  duplicate: false,
  work_order_id: 'WO-' + v.segment + '-' + Date.now().toString(36).toUpperCase(),
  segment_id: v.segment, status: 'pending_approval', priority: v.req_priority === 'P1' ? 'high' : 'normal', trigger_source: 'manager',
  tier: v.req_tier || 'unverified', horizon: v.req_horizon, score: v.score,
  summary: 'Manager-requested inspection of ' + v.segment + (v.req_why ? '. ' + v.req_why : '') + '.' + (v.req_checks[0] ? ' First check: ' + v.req_checks[0] : ''),
  facts_json: JSON.stringify(facts), drafted_at: now, decision_note: v.note || 'requested from the dashboard',
} }];

// Same rules as the draft path: notice owed means awaiting_notice and earliest_start = now + the longest notice_hours.
// A failed check is unverified. An order that owes notice is saved as pending_approval and is not sent to W9 yet.
const base = $('Build manager work order').item.json;
const r = $json || {};
const body = r.body && typeof r.body === 'object' ? r.body : null;
const now = new Date();
let status, earliest = '', detail;
if (r.statusCode === 200 && body && body.ok === true) {
  const steps = Array.isArray(body.steps) ? body.steps : [];
  const notice = steps.filter((s) => Number(s.noticeHours) > 0);
  const hours = notice.reduce((m, s) => Math.max(m, Number(s.noticeHours) || 0), 0);
  status = notice.length ? 'awaiting_notice' : String(body.status || 'unverified');
  earliest = new Date(now.getTime() + hours * 3600000).toISOString();
  detail = { check: body.status || null, notice_hours: hours, notice_steps: notice.map((s) => s.id), steps, unverified: body.unverified || [], problems: body.problems || [], summary: body.summary || null };
} else {
  status = 'unverified';
  detail = { error: (body && body.error) || (r.error && (r.error.message || String(r.error))) || ('obligation check answered ' + (r.statusCode || 'nothing')) };
}
const v = $('Validate action').first().json;
const start = v.start || now.toISOString();
const ob = { ...detail, checked_at: now.toISOString() };
if (status !== 'awaiting_notice') ob.approved_start = start;
return { json: { ...base, obligation_status: status, earliest_start: earliest, needs_notice: status === 'awaiting_notice', approved_start: start, obligation_json: JSON.stringify(ob) } };

// confirm_notice: a named person records when and how landowner notice was given.
// It goes to v2 W9 as a land_obligations decision. On W9's 200, earliest_start = notice_given_at + the longest notice_hours.
const v = $('Validate action').first().json;
const order = $input.all().map((i) => i.json).find((r) => r && r.work_order_id === v.work_order_id);
const refuse = (code, error) => [{ json: { ok: false, status_code: code, response: { ok: false, action: 'confirm_notice', segment: v.segment, work_order_id: v.work_order_id, error } } }];
if (!order) return refuse(404, 'No work order ' + v.work_order_id + '.');
if (order.resume_url) return refuse(409, 'This order was drafted by the hackathon WF4 and stays with it until switch day. v2 does not record notice on it.');
if (order.segment_id !== v.segment) return refuse(400, 'Work order ' + v.work_order_id + ' is on segment ' + order.segment_id + ', not ' + v.segment + '.');
if (order.status !== 'pending_approval') return refuse(409, 'Work order ' + v.work_order_id + ' is ' + order.status + '. Notice can only be recorded while the order waits for approval.');
if (order.obligation_status !== 'awaiting_notice') return refuse(409, order.obligation_status === 'notice_given' ? 'Notice is already recorded for this order.' : 'No landowner notice is owed on this order (obligation status: ' + (order.obligation_status || 'not checked') + ').');
let ob = {};
try { ob = JSON.parse(order.obligation_json || '{}'); } catch (e) {}
const hours = Number(ob.notice_hours) || 0;
if (!(hours > 0)) return refuse(409, 'The stored obligation check has no notice period, so earliest start cannot be recomputed.');
const earliest = new Date(new Date(v.notice_given_at).getTime() + hours * 3600000).toISOString();
return [{ json: { ok: true, work_order_id: order.work_order_id, segment_id: order.segment_id, notice_given_at: v.notice_given_at, notice_hours: hours, earliest_start: earliest, obligation_json: order.obligation_json || '' } }];

// A person redrafts an expired order: a new pending order from the same facts, with a fresh obligation check.
// The expired order stays as it is. Refused if the segment already has an open order.
const v = $('Validate action').first().json;
const DAY = 24 * 3600 * 1000;
const NOTICE = ['awaiting_notice', 'notice_given'];
const rows = $input.all().map((i) => i.json).filter((r) => r && r.work_order_id);
const refuse = (code, error) => [{ json: { ok: false, status_code: code, response: { ok: false, action: 'redraft_work_order', segment: v.segment, work_order_id: v.work_order_id, error } } }];
const old = rows.find((r) => r.work_order_id === v.work_order_id);
if (!old) return refuse(404, 'No work order ' + v.work_order_id + ' on segment ' + v.segment + '.');
if (old.resume_url) return refuse(409, 'This order was drafted by the hackathon WF4 and stays with it until switch day.');
if (old.status !== 'expired') return refuse(409, 'Only expired orders can be redrafted. This one is ' + old.status + '.');
const open = rows.find((r) => r.work_order_id !== old.work_order_id && ((r.status === 'pending_approval' && (NOTICE.includes(r.obligation_status) || !r.drafted_at || Date.now() - new Date(r.drafted_at).getTime() < 14 * DAY)) || (r.status === 'approved' && r.decided_at && Date.now() - new Date(r.decided_at).getTime() < 7 * DAY)));
if (open) return refuse(409, 'Segment ' + v.segment + ' already has an open order: ' + open.work_order_id + '.');
return [{ json: { ok: true, work_order_id: 'WO-' + old.segment_id + '-' + Date.now().toString(36).toUpperCase(), segment_id: old.segment_id, status: 'pending_approval', priority: old.priority || 'normal', trigger_source: 'redraft', tier: old.tier || '', horizon: old.horizon || 'y10', score: old.score == null ? null : old.score, summary: old.summary || '', facts_json: old.facts_json || '[]', drafted_at: new Date().toISOString(), decision_note: 'Redraft of ' + old.work_order_id + ' by ' + v.by, redraft_of: old.work_order_id } }];

// Same rules as the draft path, with fresh data: notice owed means awaiting_notice and
// earliest_start = now + the longest notice_hours. A failed check is unverified.
const base = $('Build redraft').item.json;
const r = $json || {};
const body = r.body && typeof r.body === 'object' ? r.body : null;
const now = new Date();
let status, earliest = '', detail;
if (r.statusCode === 200 && body && body.ok === true) {
  const steps = Array.isArray(body.steps) ? body.steps : [];
  const notice = steps.filter((s) => Number(s.noticeHours) > 0);
  const hours = notice.reduce((m, s) => Math.max(m, Number(s.noticeHours) || 0), 0);
  status = notice.length ? 'awaiting_notice' : String(body.status || 'unverified');
  earliest = new Date(now.getTime() + hours * 3600000).toISOString();
  detail = { check: body.status || null, notice_hours: hours, notice_steps: notice.map((s) => s.id), steps, unverified: body.unverified || [], problems: body.problems || [], summary: body.summary || null };
} else {
  status = 'unverified';
  detail = { error: (body && body.error) || (r.error && (r.error.message || String(r.error))) || ('obligation check answered ' + (r.statusCode || 'nothing')) };
}
return { json: { ...base, obligation_status: status, earliest_start: earliest, needs_notice: status === 'awaiting_notice', obligation_json: JSON.stringify({ ...detail, redraft_of: base.redraft_of, checked_at: now.toISOString() }) } };

// Orders waiting for approval for 14 days or more expire. Orders waiting on landowner notice
// (awaiting_notice / notice_given) are not on this clock. Nobody decided these, so they go to corridor_audit, not the ledger.
// Orders drafted by the hackathon WF4 (they carry a resume_url) stay with it until switch day and are skipped.
const DAY = 24 * 3600 * 1000;
const NOTICE = ['awaiting_notice', 'notice_given'];
return $input.all().map((i) => i.json)
  .filter((r) => r && r.work_order_id && !r.resume_url && r.status === 'pending_approval' && !NOTICE.includes(r.obligation_status) && r.drafted_at && Date.now() - new Date(r.drafted_at).getTime() >= 14 * DAY)
  .map((r) => ({ json: { work_order_id: r.work_order_id, segment_id: r.segment_id, drafted_at: r.drafted_at, obligation_status: r.obligation_status || null, days_waiting: Math.floor((Date.now() - new Date(r.drafted_at).getTime()) / DAY) } }));
